let flowIndex=0;const frame=document.querySelector('#flowFrame');
function presentFlow(i){const index=(i+flow.length)%flow.length,v=flow[index];frame.dataset.step=index;document.querySelector('#flowTitle').textContent=v.title;document.querySelector('#flowText').textContent=v.text;document.querySelector('#flowState').textContent=v.state;document.querySelector('#flowCounter').textContent=String(index+1).padStart(2,'0')+' / 04';document.querySelector('#flowBar').style.width=(index+1)*25+'%';document.querySelectorAll('.journey-node').forEach((node,n)=>node.classList.toggle('active',n===index));localizePage()}
function setFlow(i){flowIndex=(i+flow.length)%flow.length;presentFlow(flowIndex);document.querySelectorAll('.flow-step').forEach((b,n)=>{if(n===flowIndex)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});document.querySelectorAll('.journey-node').forEach((b,n)=>b.setAttribute('aria-pressed',n===flowIndex?'true':'false'))}
frame.querySelectorAll('.journey-node').forEach(node=>{const i=Number(node.dataset.journey);node.addEventListener('mouseenter',()=>presentFlow(i));node.addEventListener('focus',()=>presentFlow(i));node.addEventListener('click',()=>setFlow(i))});frame.addEventListener('mouseleave',()=>presentFlow(flowIndex));frame.addEventListener('focusout',e=>{if(!frame.contains(e.relatedTarget))presentFlow(flowIndex)});frame.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const r=frame.getBoundingClientRect();frame.style.setProperty('--mx',((e.clientX-r.left)/r.width*100).toFixed(1)+'%');frame.style.setProperty('--my',((e.clientY-r.top)/r.height*100).toFixed(1)+'%')});document.querySelectorAll('.flow-step').forEach(b=>{const i=Number(b.dataset.flow);b.addEventListener('mouseenter',()=>presentFlow(i));b.addEventListener('mouseleave',()=>presentFlow(flowIndex));b.addEventListener('focus',()=>presentFlow(i));b.addEventListener('blur',()=>presentFlow(flowIndex));b.addEventListener('click',()=>setFlow(i))});document.querySelector('#flowNext').addEventListener('click',()=>setFlow(flowIndex+1));
