const storySequence=document.querySelector('#storySequence');
const storyCards=[...storySequence.querySelectorAll('.story-card')];
const storySteps=[...storySequence.querySelectorAll('.story-rail-step')];
const storyCompact=window.matchMedia('(max-width:760px), (max-height:570px), (prefers-reduced-motion:reduce)');
let storyScene=-1,storyFrame=0,storyPreview=-1;
function showStoryScene(index){
  if(storyCompact.matches||storyScene===index)return;
  storyScene=index;
  storyCards.forEach((card,i)=>{card.classList.toggle('is-current',i===index);card.inert=i!==index});
  storySteps.forEach((step,i)=>{step.classList.toggle('is-current',i===index);if(i===index)step.setAttribute('aria-current','step');else step.removeAttribute('aria-current')});
  document.querySelector('#storyCounter').textContent=String(index+1).padStart(2,'0');
}
function updateStoryScene(){
  storyFrame=0;
  if(storyCompact.matches||!document.querySelector('#page-inicio').classList.contains('active'))return;
  const rect=storySequence.getBoundingClientRect();
  const travel=Math.max(1,rect.height-window.innerHeight);
  const fraction=Math.max(0,Math.min(1,-rect.top/travel));
  showStoryScene(storyPreview>=0?storyPreview:Math.min(2,Math.floor(fraction*3)));
}
function scheduleStoryScene(){if(!storyFrame)storyFrame=requestAnimationFrame(updateStoryScene)}
function adaptStoryScene(){storyCards.forEach(card=>card.inert=false);storyScene=-1;if(!storyCompact.matches)scheduleStoryScene()}
storySteps.forEach((step,i)=>{
  step.addEventListener('mouseenter',()=>{storyPreview=i;showStoryScene(i)});
  step.addEventListener('focus',()=>{storyPreview=i;showStoryScene(i)});
  step.addEventListener('click',()=>{
    storyPreview=-1;
    const distance=Math.max(1,storySequence.offsetHeight-window.innerHeight);
    const target=storySequence.getBoundingClientRect().top+window.scrollY+distance*(i+.5)/3;
    window.scrollTo({top:target,behavior:'smooth'});
  });
});
storySequence.querySelector('.story-rail').addEventListener('mouseleave',()=>{storyPreview=-1;scheduleStoryScene()});
storySequence.querySelector('.story-rail').addEventListener('focusout',event=>{if(!event.currentTarget.contains(event.relatedTarget)){storyPreview=-1;scheduleStoryScene()}});
window.addEventListener('scroll',scheduleStoryScene,{passive:true});
window.addEventListener('resize',scheduleStoryScene,{passive:true});
storyCompact.addEventListener('change',adaptStoryScene);
window.addEventListener('hashchange',scheduleStoryScene);
adaptStoryScene();

